    case RECOP_GXInvalidateVtxCache: (void)p; gxi_GXInvalidateVtxCache(); break;
    case RECOP_GXLoadTexObj: { Rec_GXLoadTexObj *r = (Rec_GXLoadTexObj *)p; gxi_GXLoadTexObj(&r->obj, r->map); break; }
    case RECOP_GXInvalidateTexAll: (void)p; gxi_GXInvalidateTexAll(); break;
    case RECOP_GXLoadPosMtxImm: { Rec_GXLoadPosMtxImm *r = (Rec_GXLoadPosMtxImm *)p; gxi_GXLoadPosMtxImm(r->m, r->id); break; }
