    case RECOP_GXSetCurrentMtx: { Rec_GXSetCurrentMtx *r = (Rec_GXSetCurrentMtx *)p; gxi_GXSetCurrentMtx(r->id); break; }
    case RECOP_GXSetProjection: { Rec_GXSetProjection *r = (Rec_GXSetProjection *)p; gxi_GXSetProjection(r->m, r->type); break; }
    case RECOP_GXSetNumChans: { Rec_GXSetNumChans *r = (Rec_GXSetNumChans *)p; gxi_GXSetNumChans(r->n); break; }
    case RECOP_GXSetChanCtrl: { Rec_GXSetChanCtrl *r = (Rec_GXSetChanCtrl *)p; gxi_GXSetChanCtrl(r->chan, r->enable, r->amb_src, r->mat_src, r->light_mask, r->diff_fn, r->attn_fn); break; }
    case RECOP_GXSetChanAmbColor: { Rec_GXSetChanAmbColor *r = (Rec_GXSetChanAmbColor *)p; gxi_GXSetChanAmbColor(r->chan, r->c); break; }
    case RECOP_GXSetChanMatColor: { Rec_GXSetChanMatColor *r = (Rec_GXSetChanMatColor *)p; gxi_GXSetChanMatColor(r->chan, r->c); break; }
